# OCR + BILL HELPERS
# ─────────────────────────────────────────────
def preprocess_image(image):
    try:
        img_array = np.array(image)
        gray = cv2.cvtColor(img_array, cv2.COLOR_RGB2GRAY) if len(img_array.shape)==3 else img_array
        gray = cv2.convertScaleAbs(gray, alpha=1.5, beta=20)
        gray = cv2.medianBlur(gray, 3)
        _, thresh = cv2.threshold(gray, 0, 255, cv2.THRESH_BINARY+cv2.THRESH_OTSU)
        return Image.fromarray(thresh)
    except:
        return image

def ocr_with_api(image_file):
    try:
        image = Image.open(image_file)
        processed = preprocess_image(image)
        buf = io.BytesIO(); processed.save(buf, format="PNG"); buf.seek(0)
        resp = requests.post("https://api.ocr.space/parse/image",
            files={"file": ("image.png", buf, "image/png")},
            data={"apikey": OCR_API_KEY, "language": "eng", "isOverlayRequired": "false",
                  "scale": "true", "isTable": "true", "OCREngine": "2"}, timeout=45)
        if resp.status_code == 200:
            r = resp.json()
            if r.get("ParsedResults"):
                return {"success": True, "text": r["ParsedResults"][0]["ParsedText"].strip(), "confidence": 95}
        return {"success": False, "text": "", "error": "API Error"}
    except Exception as e:
        return {"success": False, "text": "", "error": str(e)}

def extract_bill_data(ocr_text):
    if not ocr_text:
        return {"supplier": "Unknown", "date": datetime.now().strftime("%Y-%m-%d"), "total": 0, "materials": []}
    materials = []; total_amount = 0; supplier = "Unknown Supplier"
    lines = [l.strip() for l in ocr_text.split("\n") if l.strip()]
    for line in lines[:5]:
        if re.search(r"(cement|steel|builders|construction|ltd|pvt|supplies?|traders?)", line, re.I):
            supplier = line; break
    for line in lines:
        m = re.search(r"(cement|opc|ppc).*?(\d+(?:\.\d+)?).*?(bag|bags).*?(\d+(?:\.\d+)?)", line, re.I)
        if m: materials.append({"name": m.group(1).title(), "quantity": float(m.group(2) or 0), "unit": m.group(3), "rate": float(m.group(4) or 0), "total": 0})
        m2 = re.search(r"(steel|tmt|rod).*?(\d+(?:\.\d+)?).*?(kg|ton).*?(\d+(?:\.\d+)?)", line, re.I)
        if m2: materials.append({"name": "Steel TMT", "quantity": float(m2.group(2) or 0), "unit": m2.group(3), "rate": float(m2.group(4) or 0), "total": 0})
        tm = re.search(r"(total|amount).*?₹?([0-9,]+(?:\.[0-9]+)?)", line, re.I)
        if tm: total_amount = float(tm.group(2).replace(",", ""))
    if not materials: materials = [{"name": "Items Detected", "quantity": len(lines), "unit": "lines", "rate": 0, "total": total_amount}]
    return {"supplier": supplier, "date": datetime.now().strftime("%Y-%m-%d"), "total": int(total_amount), "materials": materials}

# ─────────────────────────────────────────────
# WEATHER API
# ─────────────────────────────────────────────
def get_real_weather_data(city):
    try:
        resp = requests.get(f"http://api.openweathermap.org/data/2.5/forecast?q={city}&appid={WEATHER_API_KEY}&units=metric", timeout=10)
        data = resp.json()
        if resp.status_code != 200: return None
        cur = data["list"][0]
        rain_expected = False; rain_times = []; forecast_data = []
        for item in data["list"][:16]:
            dt = datetime.fromtimestamp(item["dt"]); rp = item.get("pop", 0)*100
            if rp > 20: rain_expected = True; rain_times.append(f"🌧️ {dt.strftime('%I %p | %d %b')} - {rp:.0f}% ({item['weather'][0]['description']})")
            forecast_data.append({"day": dt.strftime("%A"), "temp": f"{item['main']['temp']:.0f}°C", "rain": rp})
        daily = {}
        for item in forecast_data:
            d = item["day"]
            if d not in daily: daily[d] = {"temps": [], "rain": []}
            daily[d]["temps"].append(float(item["temp"][:-2])); daily[d]["rain"].append(item["rain"])
        forecast = [{"date": d, "temp": f"{sum(v['temps'])/len(v['temps']):.0f}°C", "rain_probability": max(v["rain"])} for d,v in list(daily.items())[:3]]
        return {"current": {"temp": f"{cur['main']['temp']:.0f}", "humidity": cur["main"]["humidity"],
                            "wind": f"{cur['wind']['speed']:.0f}", "condition": cur["weather"][0]["main"]},
                "forecast": forecast, "rain_expected": rain_expected, "rain_times": rain_times[:5], "city": city.title()}
    except: return None

