# DATABASE (Offline Mode)
# ─────────────────────────────────────────────
if not os.path.exists("data"): os.makedirs("data")
DB_LOCAL = "data/local.db"
DB_MAIN  = "data/main.db"

def init_local_db():
    for db in [DB_LOCAL, DB_MAIN]:
        conn = sqlite3.connect(db); c = conn.cursor()
        c.execute("CREATE TABLE IF NOT EXISTS entries (id INTEGER PRIMARY KEY AUTOINCREMENT, data TEXT, timestamp TEXT, synced INTEGER)")
        conn.commit(); conn.close()

def save_offline(data):
    conn = sqlite3.connect(DB_LOCAL)
    conn.cursor().execute("INSERT INTO entries (data,timestamp,synced) VALUES (?,?,0)", (data, datetime.now().isoformat()))
    conn.commit(); conn.close()

def sync_data():
    local = sqlite3.connect(DB_LOCAL); main = sqlite3.connect(DB_MAIN)
    lc, mc = local.cursor(), main.cursor()
    lc.execute("SELECT * FROM entries WHERE synced=0"); rows = lc.fetchall()
    for row in rows:
        mc.execute("INSERT INTO entries (data,timestamp,synced) VALUES (?,?,1)", (row[1], row[2]))
        lc.execute("UPDATE entries SET synced=1 WHERE id=?", (row[0],))
    local.commit(); main.commit(); local.close(); main.close(); return len(rows)

