def weather_alerts():
    render_page_header("Live Weather Intelligence", "Real-time meteorological monitoring & site climate planning", "weather", "#C2410C", "#FFEDD5", "#FED7AA")
    col_input, col_btn = st.columns([3, 1])
    with col_input: city = st.text_input("Project Location / City", value="Mumbai", placeholder="Mumbai, Delhi, Bangalore...")
    with col_btn:
        st.write(""); st.write("")
        fetch = st.button("Fetch Forecast →", type="primary", use_container_width=True)
    if fetch:
        with st.spinner("Retrieving atmospheric telemetry..."):
            weather = get_real_weather_data(city)
        if weather:
            c1,c2,c3,c4 = st.columns(4)
            vals = [weather["current"]["temp"]+"°C", str(weather["current"]["humidity"])+"%",
                    weather["current"]["wind"]+" km/h", weather["current"]["condition"]]
            for c,lbl,val in zip([c1,c2,c3,c4],["Air Temperature","Relative Humidity","Wind Velocity","Atmosphere"],vals):
                with c: st.metric(lbl, val)
            if weather["rain_expected"]:
                st.markdown("""<div style="background:#FEF2F2;border:1px solid #FCA5A5;border-radius:14px;padding:20px;margin:16px 0;">
                  <div style="font-family:'Outfit',sans-serif;font-weight:700;font-size:18px;color:#B91C1C;">Precipitation Alert — Next 24–48 Hours</div>
                  <div style="color:#571E1E;font-size:13px;margin-top:4px;">Advisory: Delay outdoor concrete pours, secure cement stores and waterproof sensitive electrical installations.</div></div>""", unsafe_allow_html=True)
                with st.expander("Detailed Precipitation Timeline"):
                    for t in weather["rain_times"]: st.write(f"• {t.replace('🌧️ ', '')}")
            else:
                st.markdown("""<div style="background:#F0FDF4;border:1px solid #86EFAC;border-radius:14px;padding:20px;margin:16px 0;">
                  <div style="font-family:'Outfit',sans-serif;font-weight:700;font-size:18px;color:#15803D;">Clear Atmospheric Conditions — Next 48 Hours</div>
                  <div style="color:#1C4D2E;font-size:13px;margin-top:4px;">Zero precipitation forecasted. Optimum conditions for structural framing, exterior plaster and concrete curing.</div></div>""", unsafe_allow_html=True)
            st.markdown("### 3-Day Site Outlook")
            fc_cols = st.columns(3)
            for i, day in enumerate(weather["forecast"]):
                with fc_cols[i]:
                    rp = day["rain_probability"]; rc = "#B91C1C" if rp>60 else "#B45309" if rp>30 else "#2A724A"
                    cond_tag = "Rain Risk High" if rp>60 else "Scattered" if rp>30 else "Clear Skies"
                    st.markdown(f"""<div class="weather-card">
                      <div style="font-family:'Plus Jakarta Sans',sans-serif;font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#787067;margin-bottom:8px;">{day["date"]}</div>
                      <div class="weather-temp">{day["temp"]}</div>
                      <div style="margin-top:8px;font-size:13px;font-weight:700;color:#554D47;">{cond_tag}</div>
                      <div style="font-family:'Plus Jakarta Sans',sans-serif;font-size:12px;font-weight:700;color:{rc};margin-top:4px;">{rp:.0f}% Probability</div>
                    </div>""", unsafe_allow_html=True)
            st.markdown(f'<div style="background:#EDF7F1;border:1px solid #B8DEC8;border-radius:8px;padding:10px 14px;margin-top:14px;font-size:12px;color:#2A724A;font-weight:600;">Telemetry verified for <b>{weather["city"]}</b> &bull; Updated live</div>', unsafe_allow_html=True)
        else:
            st.error(f"Station data for '{city}' could not be located. Try: Mumbai, Delhi, Bengaluru, Pune.")
    if st.button("Load Station Demo Data", type="secondary"):
        st.info("Demonstration telemetry: Mumbai — 28°C, Clear skies, 65% humidity")

