def chatbot():
    render_page_header("AI Technical Assistant", "Civil engineering & IS code technical intelligence", "chatbot", "#7E22CE", "#F3E8FF", "#E9D5FF")
    genai.configure(api_key=CHATBOT_API_KEY)
    model = genai.GenerativeModel("gemini-2.5-flash")
    if "chat_history" not in st.session_state: st.session_state.chat_history = []
    st.markdown('<div class="ba-card" style="min-height:300px;max-height:500px;overflow-y:auto;">', unsafe_allow_html=True)
    if not st.session_state.chat_history:
        st.markdown(f"""<div style="text-align:center;padding:40px;color:#787067;">
          <div style="display:inline-flex;align-items:center;justify-content:center;width:68px;height:68px;background:#F3E8FF;border:1px solid #E9D5FF;border-radius:20px;margin-bottom:14px;">
            {svg_icon('chatbot', '#7E22CE', 36, 2)}
          </div>
          <div style="font-family:'Outfit',sans-serif;font-size:22px;font-weight:700;color:#231F20;">Construction Technical Intelligence</div>
          <div style="font-size:13px;margin-top:6px;color:#787067;">Material specifications &bull; Safety protocols &bull; Project schedules &bull; Indian IS Codes</div>
        </div>""", unsafe_allow_html=True)
    else:
        for role, msg in st.session_state.chat_history:
            if role == "You":
                st.markdown(f'<div class="chat-you"><div class="chat-label chat-label-you">FIELD ENGINEER</div><div style="font-size:14px;color:#231F20;line-height:1.6;">{msg}</div></div>', unsafe_allow_html=True)
            else:
                st.markdown(f'<div class="chat-ai"><div class="chat-label chat-label-ai">BUILDATLAS ASSISTANT</div><div style="font-size:14px;color:#231F20;line-height:1.6;">{msg}</div></div>', unsafe_allow_html=True)
    st.markdown("</div>", unsafe_allow_html=True)
    col_input, col_btn, col_clear = st.columns([5, 1, 1])
    with col_input: user_input = st.text_input("Message", placeholder="Ask about construction...", label_visibility="collapsed", key="chat_input")
    with col_btn: send = st.button("Send Query →", type="primary", use_container_width=True)
    with col_clear:
        if st.button("Clear Log", type="secondary", use_container_width=True):
            st.session_state.chat_history = []; st.rerun()
    if send and user_input:
        try:
            with st.spinner("Synthesizing civil engineering response..."):
                response = model.generate_content(user_input)
            st.session_state.chat_history.append(("You", user_input))
            st.session_state.chat_history.append(("AI", response.text))
            st.rerun()
        except Exception as e:
            st.error(f"Technical Query Error: {e}")

