# PAGE 7 — DISASTER ALERTS
# ═══════════════════════════════════════════════
def disaster_page():
    render_page_header("Seismic Activity Monitor", "Live USGS earthquake telemetry & tectonic risk alerts", "disaster", "#B91C1C", "#FEE2E2", "#FECACA")
    with st.spinner("Querying USGS live seismic feed..."):
        try:
            data = requests.get("https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_day.geojson", timeout=10).json()
            earthquakes = []
            for eq in data["features"]:
                props = eq["properties"]; coords = eq["geometry"]["coordinates"]
                lon, lat = coords[0], coords[1]; place = props.get("place",""); mag = props.get("mag",0)
                if place and 8<=lat<=37 and 70<=lon<=90 and "India" in place:
                    risk = "High Risk" if mag>=6 else "Moderate" if mag>=4 else "Normal"
                    earthquakes.append({"Location": place, "Magnitude": mag, "Risk": risk})
            if earthquakes:
                n = len(earthquakes)
                st.markdown(f'<div style="background:#FEF2F2;border:1px solid #FCA5A5;border-radius:14px;padding:18px;margin-bottom:20px;"><div style="font-family:\'Outfit\',sans-serif;font-weight:700;font-size:18px;color:#B91C1C;">{n} Seismic Event(s) Detected in India Region Today</div></div>', unsafe_allow_html=True)
                df = pd.DataFrame(earthquakes); st.dataframe(df, use_container_width=True)
                fig = px.bar(df, x="Location", y="Magnitude", color="Magnitude",
                             color_continuous_scale=["#2A724A","#B45309","#B91C1C"], title="Earthquake Magnitude Distribution")
                fig = apply_dark(fig); fig.update_coloraxes(showscale=False); st.plotly_chart(fig, use_container_width=True)
            else:
                st.markdown(f"""<div style="background:#F0FDF4;border:1px solid #86EFAC;border-radius:16px;padding:32px;text-align:center;">
                  <div style="display:inline-flex;align-items:center;justify-content:center;width:64px;height:64px;background:#DCFCE7;border-radius:50%;margin-bottom:12px;">
                    {svg_icon('shield', '#15803D', 32, 2.2)}
                  </div>
                  <div style="font-family:'Outfit',sans-serif;font-weight:700;font-size:22px;color:#15803D;">No Significant Seismic Activity Detected</div>
                  <div style="color:#1C4D2E;margin-top:6px;font-size:13px;">Regional seismic status: Normal &mdash; All structural foundation and site operations clear to proceed</div>
                </div>""", unsafe_allow_html=True)
        except Exception as e:
            st.error(f"Unable to retrieve live USGS feed: {e}")

