def labour():
    render_page_header("Workforce & Labour Manager", "Real-time crew muster roll, shifts & site productivity", "labour", "#854D0E", "#FEF3C7", "#FDE68A")
    if "workers_data" not in st.session_state:
        st.session_state.workers_data = pd.DataFrame({
            "ID":[f"W{i:03d}" for i in range(1,152)],
            "Name":[f"Worker {i}" for i in range(1,152)],
            "Status":["Present"]*142+["Half Day"]*5+["Absent"]*4,
            "Hours":[8.0]*142+[4.0]*5+[0.0]*4
        })
    df = st.session_state.workers_data
    pc = len(df[df["Status"]=="Present"]); hc = len(df[df["Status"]=="Half Day"])
    ac = len(df[df["Status"]=="Absent"]); tw = len(df); prod = int((pc/tw)*100)
    c1,c2,c3,c4 = st.columns(4)
    with c1: st.metric("Active Present", pc)
    with c2: st.metric("Half Day Shifts", hc)
    with c3: st.metric("Absentee Count", ac)
    with c4: st.metric("Crew Productivity", f"{prod}%")
    col_main, col_chart = st.columns([2, 1])
    with col_main:
        st.markdown(f'<div class="ba-card"><div class="ba-card-title">{svg_icon("labour", "#854D0E", 18, 2)} Individual Muster Control</div>', unsafe_allow_html=True)
        search = st.text_input("Filter by ID or Name", placeholder="e.g. W005 or Worker 12", key="labour_search")
        fdf = df if not search else df[df["ID"].str.contains(search,na=False)|df["Name"].str.contains(search,na=False)]
        for idx, row in fdf.head(15).iterrows():
            wid = row["ID"]
            scol = {"Present":"#2A724A","Half Day":"#B45309","Absent":"#B91C1C"}.get(row["Status"],"#787067")
            sbg = {"Present":"#EDF7F1","Half Day":"#FEF3C7","Absent":"#FEE2E2"}.get(row["Status"],"#FAF6F0")
            c1,c2,c3,c4,c5,c6 = st.columns([0.8,2.2,2,1,1,1])
            with c1: st.markdown(f"<code style='color:#787067;font-size:11px;background:#FAF8F5;padding:2px 6px;border-radius:4px;border:1px solid #E5DFD5;'>{wid}</code>", unsafe_allow_html=True)
            with c2: st.markdown(f"<span style='color:#231F20;font-weight:600;font-size:13px;'>{row['Name']}</span>", unsafe_allow_html=True)
            with c3: st.markdown(f"<span style='font-size:11px;font-weight:700;color:{scol};background:{sbg};padding:3px 8px;border-radius:12px;display:inline-block;'>{row['Status']}</span>", unsafe_allow_html=True)
            with c4:
                if st.button("Pres", key=f"p_{wid}"): df.loc[df["ID"]==wid,"Status"]="Present"; df.loc[df["ID"]==wid,"Hours"]=8.0; st.session_state.workers_data=df; st.rerun()
            with c5:
                if st.button("Half", key=f"h_{wid}"): df.loc[df["ID"]==wid,"Status"]="Half Day"; df.loc[df["ID"]==wid,"Hours"]=4.0; st.session_state.workers_data=df; st.rerun()
            with c6:
                if st.button("Abs", key=f"a_{wid}"): df.loc[df["ID"]==wid,"Status"]="Absent"; df.loc[df["ID"]==wid,"Hours"]=0.0; st.session_state.workers_data=df; st.rerun()
        st.markdown("</div>", unsafe_allow_html=True)
        st.markdown(f'<div class="ba-card"><div class="ba-card-title">{svg_icon("crane", "#854D0E", 18, 2)} Batch Muster Actions</div>', unsafe_allow_html=True)
        b1,b2,b3 = st.columns(3)
        with b1:
            if st.button("Mark All Present", use_container_width=True): df["Status"]="Present"; df["Hours"]=8.0; st.session_state.workers_data=df; st.rerun()
        with b2:
            if st.button("50% Half Day Rotation", use_container_width=True):
                hi = np.random.choice(df.index, size=len(df)//2, replace=False); df.loc[hi,"Status"]="Half Day"; df.loc[hi,"Hours"]=4.0; st.session_state.workers_data=df; st.rerun()
        with b3:
            if st.button("Mark All Absent", use_container_width=True): df["Status"]="Absent"; df["Hours"]=0.0; st.session_state.workers_data=df; st.rerun()
        st.markdown("</div>", unsafe_allow_html=True)
        csv = df.to_csv(index=False).encode("utf-8")
        st.download_button("Export Muster Log (CSV) →", csv, "attendance.csv", "text/csv", use_container_width=True)
    with col_chart:
        fig = go.Figure(go.Pie(values=[pc,hc,ac], labels=["Present","Half Day","Absent"],
                               marker_colors=["#2A724A","#B45309","#B91C1C"], hole=0.6))
        fig = apply_dark(fig); fig.update_layout(title="Workforce Allocation",
                              annotations=[dict(text=f"{prod}%", font_size=24, font_color="#231F20", showarrow=False)])
        st.plotly_chart(fig, use_container_width=True)
        hd = df.groupby("Status")["Hours"].sum().reset_index()
        fig2 = px.bar(hd, x="Status", y="Hours", color="Status",
                      color_discrete_map={"Present":"#2A724A","Half Day":"#B45309","Absent":"#B91C1C"}, title="Logged Shift Hours by Status")
        fig2 = apply_dark(fig2); fig2.update_layout(showlegend=False); st.plotly_chart(fig2, use_container_width=True)

