HOUSE_3D_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>3D House Generator</title>\n<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>\n<style>\n@import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;600;700;800&family=Plus+Jakarta+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap\');\n*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}\n:root{--bg:#FBF9F5;--surface:#F5F1EA;--card:#FFFFFF;--border:#E5DFD5;--accent:#C85A32;--accent2:#D9822B;--text:#231F20;--muted:#787067;}\nbody{background:var(--bg);color:var(--text);font-family:\'Plus Jakarta Sans\',sans-serif;display:flex;height:100vh;overflow:hidden;}\n#sidebar{width:290px;min-width:290px;background:var(--surface);border-right:1px solid var(--border);display:flex;flex-direction:column;overflow-y:auto;z-index:10;}\n.logo{padding:22px 20px 18px;border-bottom:1px solid var(--border);}\n.logo h1{font-family:\'Outfit\',sans-serif;font-size:22px;font-weight:800;color:var(--accent);}\n.logo p{font-size:9px;color:var(--muted);margin-top:4px;letter-spacing:1.5px;text-transform:uppercase;font-weight:600;}\n.section{padding:14px 16px;border-bottom:1px solid var(--border);}\n.sec-title{font-family:\'Outfit\',sans-serif;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:var(--muted);margin-bottom:12px;}\n.input-group{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;}\n.num-field{display:flex;flex-direction:column;background:var(--card);border:1px solid var(--border);border-radius:8px;padding:10px 12px;}\n.num-field span{font-size:8px;color:var(--muted);letter-spacing:1px;text-transform:uppercase;margin-bottom:5px;font-weight:700;}\n.num-field input{background:none;border:none;color:var(--text);font-family:\'JetBrains Mono\',monospace;font-size:20px;font-weight:600;width:100%;outline:none;-moz-appearance:textfield;}\n.num-field input::-webkit-inner-spin-button,.num-field input::-webkit-outer-spin-button{-webkit-appearance:none}\n.field{margin-bottom:12px;}\n.field label{display:flex;justify-content:space-between;font-size:11px;color:var(--muted);margin-bottom:6px;font-weight:600;}\n.field label .val{color:var(--accent);background:#FAF0EB;padding:1px 8px;border-radius:4px;border:1px solid #F0D5C7;}\ninput[type=range]{width:100%;-webkit-appearance:none;height:4px;background:var(--border);border-radius:2px;outline:none;cursor:pointer;}\ninput[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:14px;height:14px;border-radius:50%;background:var(--accent);border:2px solid #FFFFFF;box-shadow:0 1px 4px rgba(0,0,0,0.2);cursor:pointer;}\n.preset-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px;}\n.preset{padding:10px 6px;border:1px solid var(--border);border-radius:8px;background:var(--card);cursor:pointer;text-align:center;transition:all .2s;}\n.preset.active{border-color:var(--accent);background:#FAF0EB;}\n.preset-icon{font-size:20px;display:block;margin-bottom:3px;}\n.preset-name{font-size:9px;color:var(--text);letter-spacing:0.5px;font-weight:700;text-transform:uppercase;}\n.color-row{display:grid;grid-template-columns:1fr 1fr 1fr;gap:7px;}\n.color-ctrl label{font-size:9px;color:var(--muted);display:block;margin-bottom:4px;text-transform:uppercase;font-weight:700;}\n.color-ctrl input[type=color]{width:100%;height:28px;border:1px solid var(--border);border-radius:6px;background:none;cursor:pointer;padding:2px;}\n#generateBtn{margin:14px 16px;padding:13px;background:linear-gradient(135deg,var(--accent),#b84a24);border:none;border-radius:10px;color:#FFFFFF;font-family:\'Outfit\',sans-serif;font-size:13px;font-weight:800;letter-spacing:0.5px;text-transform:uppercase;cursor:pointer;box-shadow:0 2px 8px rgba(200,90,50,0.25);transition:all .2s;}\n#generateBtn:hover{transform:translateY(-2px);box-shadow:0 6px 16px rgba(200,90,50,0.35);}\n#stats{padding:12px 16px;background:var(--card);border-top:1px solid var(--border);display:grid;grid-template-columns:1fr 1fr;gap:8px;}\n.stat .s-label{font-size:8px;color:var(--muted);letter-spacing:1px;text-transform:uppercase;font-weight:700;}\n.stat .s-val{font-size:13px;color:var(--accent);font-weight:700;}\n#canvasWrap{flex:1;position:relative;overflow:hidden;background:radial-gradient(ellipse at 50% 30%,#FAF6EE,#E5DFD5 70%);}\n#hud{position:absolute;top:14px;right:14px;}\n.hud-chip{background:rgba(255,255,255,.92);border:1px solid var(--border);border-radius:8px;padding:6px 12px;font-size:10px;color:var(--text);font-weight:600;box-shadow:0 2px 6px rgba(0,0,0,0.05);}\n#camControls{position:absolute;bottom:18px;right:18px;display:flex;gap:7px;}\n.cam-btn{width:34px;height:34px;border-radius:8px;background:rgba(255,255,255,.92);border:1px solid var(--border);color:var(--muted);font-size:14px;cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 6px rgba(0,0,0,0.05);transition:all .15s;}\n.cam-btn:hover{border-color:var(--accent);color:var(--accent);}\n#toast{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);background:var(--accent);color:#FFFFFF;font-family:\'Outfit\',sans-serif;font-size:14px;font-weight:800;padding:14px 28px;border-radius:10px;box-shadow:0 6px 20px rgba(200,90,50,0.3);opacity:0;transition:opacity .3s;pointer-events:none;}\n#toast.show{opacity:1}\n</style>\n</head>\n<body>\n<div id="sidebar">\n  <div class="logo"><h1>House Generator</h1><p>Architectural 3D Visualizer</p></div>\n  <div class="section"><div class="sec-title">Building Info</div><div class="input-group"><div class="num-field"><span>Land (m²)</span><input type="number" id="landArea" value="200" min="50" max="2000"></div><div class="num-field"><span>Floors</span><input type="number" id="floors" value="2" min="1" max="6"></div></div></div>\n  <div class="section"><div class="sec-title">Room Layout</div><div class="input-group"><div class="num-field"><span>Total Rooms</span><input type="number" id="totalRooms" value="6" min="2" max="20"></div><div class="num-field"><span>Bedrooms</span><input type="number" id="bedrooms" value="3" min="1" max="10"></div></div><div class="input-group"><div class="num-field"><span>Bathrooms</span><input type="number" id="bathrooms" value="2" min="1" max="8"></div><div class="num-field"><span>Garage</span><input type="number" id="garage" value="1" min="0" max="4"></div></div></div>\n  <div class="section"><div class="sec-title">Design Controls</div><div class="field"><label>Roof Pitch <span class="val" id="pitchVal">35°</span></label><input type="range" id="roofPitch" min="10" max="60" value="35"></div><div class="field"><label>Windows <span class="val" id="winVal">Medium</span></label><input type="range" id="windowDensity" min="1" max="3" value="2"></div><div class="field"><label>Balcony Depth <span class="val" id="balcVal">1.0m</span></label><input type="range" id="balconyDepth" min="0" max="3" value="1" step="0.5"></div></div>\n  <div class="section"><div class="sec-title">Style</div><div class="preset-grid"><div class="preset active" data-style="modern"><span class="preset-icon">🏛️</span><span class="preset-name">Modern</span></div><div class="preset" data-style="colonial"><span class="preset-icon">🏡</span><span class="preset-name">Colonial</span></div><div class="preset" data-style="minimal"><span class="preset-icon">⬛</span><span class="preset-name">Minimal</span></div><div class="preset" data-style="villa"><span class="preset-icon">🏰</span><span class="preset-name">Villa</span></div></div></div>\n  <div class="section"><div class="sec-title">Colors</div><div class="color-row"><div class="color-ctrl"><label>Walls</label><input type="color" id="wallColor" value="#c8b89a"></div><div class="color-ctrl"><label>Roof</label><input type="color" id="roofColor" value="#4a3728"></div><div class="color-ctrl"><label>Trim</label><input type="color" id="trimColor" value="#f0ede8"></div></div></div>\n  <button id="generateBtn">⚡ Generate House</button>\n  <div id="stats"><div class="stat"><span class="s-label">Land Area</span><span class="s-val" id="s-area">—</span></div><div class="stat"><span class="s-label">Floors</span><span class="s-val" id="s-floors">—</span></div><div class="stat"><span class="s-label">Rooms/Floor</span><span class="s-val" id="s-rpf">—</span></div><div class="stat"><span class="s-label">Style</span><span class="s-val" id="s-style">—</span></div></div>\n</div>\n<div id="canvasWrap"><canvas id="threeCanvas"></canvas><div id="hud"><div class="hud-chip" id="hudInfo">Click Generate to build</div></div><div id="camControls"><button class="cam-btn" id="camFront">🔲</button><button class="cam-btn" id="camSide">◀</button><button class="cam-btn" id="camTop">▲</button><button class="cam-btn" id="camPersp">◈</button></div><div id="toast">✓ House Generated!</div></div>\n<script>\nconst canvas=document.getElementById("threeCanvas"),wrap=document.getElementById("canvasWrap");\nconst renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});\nrenderer.setPixelRatio(Math.min(window.devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;\nconst scene=new THREE.Scene();scene.background=new THREE.Color("#ECE7DF");scene.fog=new THREE.FogExp2("#ECE7DF",.012);\nconst camera=new THREE.PerspectiveCamera(45,1,.1,500);camera.position.set(18,10,22);\nscene.add(new THREE.AmbientLight(0xfff8ee,.8));\nconst sun=new THREE.DirectionalLight(0xfff4e0,1.7);sun.position.set(15,28,12);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);["left","right","top","bottom"].forEach((s,i)=>sun.shadow.camera[s]=[-28,28,28,-28][i]);sun.shadow.camera.far=100;scene.add(sun);\nconst fill=new THREE.DirectionalLight(0xe8d0b8,.4);fill.position.set(-10,5,-8);scene.add(fill);\nconst ground=new THREE.Mesh(new THREE.PlaneGeometry(120,120),new THREE.MeshStandardMaterial({color:0xd5ccbe,roughness:.95}));ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;scene.add(ground);\nlet drag=false,pX=0,pY=0,theta=0.6,phi=0.44,radius=30;const tgt=new THREE.Vector3(0,3,0);\nfunction camUpdate(){camera.position.set(tgt.x+radius*Math.sin(theta)*Math.cos(phi),tgt.y+radius*Math.sin(phi),tgt.z+radius*Math.cos(theta)*Math.cos(phi));camera.lookAt(tgt);}camUpdate();\ncanvas.addEventListener("mousedown",e=>{drag=true;pX=e.clientX;pY=e.clientY});window.addEventListener("mouseup",()=>drag=false);\nwindow.addEventListener("mousemove",e=>{if(!drag)return;theta-=(e.clientX-pX)*.008;phi=Math.max(.05,Math.min(1.4,phi+(e.clientY-pY)*.006));pX=e.clientX;pY=e.clientY;camUpdate();});\ncanvas.addEventListener("wheel",e=>{radius=Math.max(6,Math.min(60,radius+e.deltaY*.04));camUpdate();e.preventDefault();},{passive:false});\ndocument.getElementById("camFront").onclick=()=>{theta=0;phi=.25;radius=28;camUpdate()};document.getElementById("camSide").onclick=()=>{theta=Math.PI/2;phi=.25;radius=28;camUpdate()};document.getElementById("camTop").onclick=()=>{theta=.001;phi=1.35;radius=32;camUpdate()};document.getElementById("camPersp").onclick=()=>{theta=0.6;phi=.44;radius=30;camUpdate()};\nlet currentStyle="modern";document.querySelectorAll(".preset").forEach(p=>{p.addEventListener("click",()=>{document.querySelectorAll(".preset").forEach(x=>x.classList.remove("active"));p.classList.add("active");currentStyle=p.dataset.style;});});\nconst mkMat=(hex,r=.76,m=0)=>new THREE.MeshStandardMaterial({color:new THREE.Color(hex),roughness:r,metalness:m});\nfunction bx(w,h,d,mat,x,y,z,cs=true){const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);mesh.position.set(x,y,z);mesh.castShadow=cs;mesh.receiveShadow=true;return mesh;}\nlet houseGroup=null;\nfunction generateHouse(){if(houseGroup){scene.remove(houseGroup);houseGroup=null;}\nconst floors=Math.max(1,Math.min(6,parseInt(document.getElementById("floors").value)||2));const landArea=Math.max(50,parseFloat(document.getElementById("landArea").value)||200);const totalRooms=parseInt(document.getElementById("totalRooms").value)||6;const garageSlots=parseInt(document.getElementById("garage").value)||1;const roofPitch=parseInt(document.getElementById("roofPitch").value)||35;const winDensity=parseInt(document.getElementById("windowDensity").value)||2;const balcDepth=parseFloat(document.getElementById("balconyDepth").value)||0;\nconst wallHex=document.getElementById("wallColor").value;const roofHex=document.getElementById("roofColor").value;const trimHex=document.getElementById("trimColor").value;\nconst fp=Math.sqrt(landArea*.5),W=Math.min(fp*1.3,18),D=Math.min(fp*.9,13),fH=3.2;const pitchRad=(roofPitch*Math.PI)/180,roofH=(D/2)*Math.tan(pitchRad);\nconst wallMat=mkMat(wallHex,.78),roofMat=mkMat(roofHex,.85,.05),trimMat=mkMat(trimHex,.6);const glassMat=new THREE.MeshStandardMaterial({color:0x98b8d8,roughness:.05,metalness:.1,transparent:true,opacity:.5});const doorMat=mkMat("#3d2b1f",.7),concMat=mkMat("#b0a89c",.9),garMat=mkMat("#3a3530",.85);\nhouseGroup=new THREE.Group();for(let f=0;f<floors;f++){const yb=f*fH;houseGroup.add(bx(W,fH,D,wallMat,0,yb+fH/2,0));if(f>0)houseGroup.add(bx(W+.1,.22,D+.1,trimMat,0,yb+.08,0));[-W/2,W/2].forEach(cx=>{[-D/2,D/2].forEach(cz=>{houseGroup.add(bx(.28,fH+.1,.28,trimMat,cx,yb+fH/2,cz));});});const wCt={1:2,2:3,3:4}[winDensity]||2,winW=1.1,winH=1.4;for(let wi=0;wi<wCt;wi++){const wx=-W/2+(W/(wCt+1))*(wi+1),wy=yb+fH*.62;houseGroup.add(bx(winW,winH,.1,glassMat,wx,wy,D/2+.02));[-winW/2-.06,winW/2+.06].forEach(fx=>houseGroup.add(bx(.1,winH+.14,.12,trimMat,wx+fx,wy,D/2+.02)));[-winH/2-.06,winH/2+.06].forEach(fy=>houseGroup.add(bx(winW+.2,.1,.12,trimMat,wx,wy+fy,D/2+.02)));}if(f>0&&balcDepth>0&&currentStyle!=="minimal"){const bW=W*.68;houseGroup.add(bx(bW,.18,balcDepth,concMat,0,yb-.12,D/2+balcDepth/2));houseGroup.add(bx(bW,1,.06,glassMat,0,yb+.9-.12,D/2+balcDepth+.02));[-bW/2,bW/2].forEach(xr=>houseGroup.add(bx(.06,1,balcDepth,trimMat,xr,yb+.9-.12,D/2+balcDepth/2)));}}\nconst rb=floors*fH,oh={modern:.4,colonial:.65,minimal:0,villa:.85}[currentStyle]||.4;if(currentStyle==="minimal"){houseGroup.add(bx(W+.1,.3,D+.1,roofMat,0,rb+.15,0));}else{const shape=new THREE.Shape();shape.moveTo(-W/2-oh,0);shape.lineTo(W/2+oh,0);shape.lineTo(W/2+oh,.22);shape.lineTo(0,roofH+.22);shape.lineTo(-W/2-oh,.22);shape.closePath();const roofMesh=new THREE.Mesh(new THREE.ExtrudeGeometry(shape,{depth:D+oh*2,bevelEnabled:false}),roofMat);roofMesh.position.set(0,rb,-D/2-oh);roofMesh.castShadow=true;houseGroup.add(roofMesh);[-D/2-oh,D/2+oh].forEach(zg=>{const gs=new THREE.Shape();gs.moveTo(-W/2-oh,0);gs.lineTo(W/2+oh,0);gs.lineTo(0,roofH+.22);gs.closePath();const gm=new THREE.Mesh(new THREE.ShapeGeometry(gs),wallMat);gm.position.set(0,rb,zg);houseGroup.add(gm);});}\nconst dW=1.3,dH=2.5;houseGroup.add(bx(dW,dH,.12,doorMat,0,.1+dH/2,D/2+.07));houseGroup.add(bx(dW+1.6,.18,1.3,concMat,0,.09,D/2+.85));if(garageSlots>0){const gW=garageSlots*3.2+.4,gH=2.6,gD=5,gx=W/2+gW/2+.1;houseGroup.add(bx(gW,gH,gD,wallMat,gx,gH/2,-D/2+gD/2));houseGroup.add(bx(gW-.3,gH-.3,.1,garMat,gx,gH/2,gD/2-D/2+.1));houseGroup.add(bx(gW+.4,.25,gD+.4,roofMat,gx,gH+.13,-D/2+gD/2));}\nhouseGroup.add(bx(W+.35,.5,D+.35,concMat,0,.25,0));function tree(x,z,h=3.2,r=1.3){houseGroup.add(bx(.22,h*.7,.22,mkMat("#5a3c22",.9),x,h*.35,z));const lv=new THREE.Mesh(new THREE.SphereGeometry(r,8,6),mkMat("#3b5d38",.9));lv.position.set(x,h*.7+r*.5,z);lv.castShadow=true;houseGroup.add(lv);}tree(-W/2-3,D/2+2.5);tree(W/2+2,D/2+3);tree(-W/2-2,-D/2-2.5,2.5,1.1);\nscene.add(houseGroup);document.getElementById("s-area").textContent=landArea+"m²";document.getElementById("s-floors").textContent=floors;document.getElementById("s-rpf").textContent=Math.ceil(totalRooms/floors);document.getElementById("s-style").textContent=currentStyle[0].toUpperCase()+currentStyle.slice(1);document.getElementById("hudInfo").innerHTML=floors+"F · "+totalRooms+" rooms";theta=0.6;phi=.42;radius=Math.max(22,Math.min(44,W+D+12));camUpdate();const toast=document.getElementById("toast");toast.classList.add("show");setTimeout(()=>toast.classList.remove("show"),1800);}\ndocument.getElementById("generateBtn").addEventListener("click",generateHouse);document.getElementById("roofPitch").addEventListener("input",function(){document.getElementById("pitchVal").textContent=this.value+"°";});document.getElementById("windowDensity").addEventListener("input",function(){document.getElementById("winVal").textContent={1:"Low",2:"Medium",3:"High"}[this.value];});document.getElementById("balconyDepth").addEventListener("input",function(){document.getElementById("balcVal").textContent=this.value+"m";});\nfunction resize(){const w=wrap.clientWidth,h=wrap.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();}window.addEventListener("resize",resize);resize();\nlet t=0;(function animate(){requestAnimationFrame(animate);t+=.004;if(houseGroup)houseGroup.position.y=Math.sin(t)*.035;renderer.render(scene,camera);})();generateHouse();\n</script></body></html>\n'

def design_generator():
    render_page_header("3D House Generator", "Interactive parametric architectural visualization engine", "design", "#0F766E", "#CCFBF1", "#99F6E4")
    st.info("Enter building parameters in the left control panel, then click Render 3D Structure. Drag canvas to rotate orbit view, scroll to zoom.")
    components.html(HOUSE_3D_HTML, height=720, scrolling=False)

# ═══════════════════════════════════════════════
# PAGE 10 — OFFLINE MODE
# ═══════════════════════════════════════════════
def page_offline():
    render_page_header("Offline System & Local Cache", "Field edge database storage with bidirectional sync", "offline", "#4B5563", "#F3F4F6", "#E5E7EB")
    col1, col2 = st.columns(2)
    with col1:
        st.markdown(f'<div class="ba-card"><div class="ba-card-title">{svg_icon("offline", "#4B5563", 18, 2)} Save Data Locally</div>', unsafe_allow_html=True)
        data = st.text_input("Enter Site Data", placeholder="e.g. Foundation work completed on Block A")
        if st.button("Save to Offline Cache →", type="primary", use_container_width=True):
            if data.strip(): save_offline(data); st.success("Saved to local edge cache successfully.")
            else: st.warning("Please provide valid site entry text.")
        st.markdown("</div>", unsafe_allow_html=True)
    with col2:
        st.markdown(f'<div class="ba-card"><div class="ba-card-title">{svg_icon("crane", "#4B5563", 18, 2)} Database Synchronization</div>', unsafe_allow_html=True)
        if st.button("Sync with Central Database →", type="primary", use_container_width=True):
            synced = sync_data()
            if synced > 0: st.success(f"{synced} record(s) synced successfully.")
            else: st.info("All local records are currently synchronized.")
        st.markdown("</div>", unsafe_allow_html=True)
    st.markdown(f'<div class="ba-card"><div class="ba-card-title">{svg_icon("bill", "#4B5563", 18, 2)} Local Storage Records</div>', unsafe_allow_html=True)
    try:
        conn = sqlite3.connect(DB_LOCAL)
        df_local = pd.read_sql_query("SELECT id, data, timestamp, CASE WHEN synced=1 THEN 'Synced' ELSE 'Pending' END as status FROM entries ORDER BY id DESC LIMIT 20", conn)
        conn.close()
        if len(df_local) > 0: st.dataframe(df_local, use_container_width=True)
        else: st.info("No local entries found. Add site data above.")
    except: st.info("Database initialized upon first record creation.")
    st.markdown("</div>", unsafe_allow_html=True)

# ═══════════════════════════════════════════════
# MAIN NAVIGATION
# ═══════════════════════════════════════════════
def main():
    init_local_db()

    pages = {
        "Dashboard":         dashboard,
        "Cost Calculator":   cost_prediction,
        "Bill Scanner":      bill_scanner,
        "Progress Tracker":  image_progress,
        "Weather Live":      weather_alerts,
        "AI Chatbot":        chatbot,
        "Disaster Alerts":   disaster_page,
        "Labour Manager":    labour,
        "Design Generator":  design_generator,
        "Offline System":    page_offline,
    }

    with st.sidebar:
        st.markdown(f"""
        <div class="sidebar-logo" style="text-align:center;padding:18px 12px 14px;">
          <div style="display:flex;justify-content:center;margin-bottom:8px;">
            {get_logo_html(height=52)}
          </div>
          <p style="color:#787067;font-size:9px;letter-spacing:1px;text-transform:uppercase;font-weight:700;margin:0;">Precision Site Intelligence</p>
        </div>
        """, unsafe_allow_html=True)

        cur = st.session_state.get("selected_page", "Dashboard")
        st.markdown(f"""
        <div style="padding:12px 14px;background:#FAF6F0;border:1px solid #DCD1C0;border-radius:12px;margin-bottom:14px;">
          <div style="font-family:'Plus Jakarta Sans',sans-serif;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#787067;margin-bottom:4px;">Active Workspace</div>
          <div style="font-family:'Outfit',sans-serif;font-size:16px;font-weight:700;color:#231F20;">{cur}</div>
        </div>
        """, unsafe_allow_html=True)

        if cur != "Dashboard":
            if st.button("← Back to Dashboard", use_container_width=True):
                st.session_state.selected_page = "Dashboard"
                st.rerun()

        st.markdown("---")
        st.markdown('<div style="font-family:\'Plus Jakarta Sans\',sans-serif;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#787067;margin-bottom:10px;">Studio Modules</div>', unsafe_allow_html=True)
        for pname in list(pages.keys())[1:]:
            is_active = (cur == pname)
            btn_type = "primary" if is_active else "secondary"
            if st.button(pname, key=f"sb_{pname}", type=btn_type, use_container_width=True):
                st.session_state.selected_page = pname
                st.rerun()

    selected = st.session_state.get("selected_page", "Dashboard")
    if selected in pages:
        pages[selected]()
    else:
        dashboard()

if __name__ == "__main__":
    main()
